/**
 * MCP `tools/call` over HTTP is delivered at most once per model request.
 *
 * Invariant (docs/INVARIANTS.md I-EFFECT-1): a mutating tool call whose delivery is ambiguous (the server may have
 * received it) is never re-sent; the outcome is reported as UNKNOWN, not as a confirmed failure. Only a definitive
 * "this route does not exist" answer (404/405/501 from /message) lets the client try the legacy base URL, because
 * then the request provably was not processed. Reads (initialize, tools/list) keep the old try-both behaviour.
 *
 * Provenance: found by audit 2026-11-17 (mcp.ts sendRequest re-POSTed the same payload on ANY fetch failure,
 * including a reset or timeout after the server had already received the request).
 */
import "./helpers/leak_guard.js";
import { describe, test } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import type { AddressInfo } from "node:net";
import { McpConnection } from "../src/mcp.js";

interface Seen { path: string; method: string }

async function withServer(
  handler: (seen: Seen, body: any, req: http.IncomingMessage, res: http.ServerResponse) => void,
  run: (url: string, calls: Seen[]) => Promise<void>,
): Promise<void> {
  const calls: Seen[] = [];
  const server = http.createServer((req, res) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      let body: any = {};
      try { body = JSON.parse(raw); } catch { /* not JSON */ }
      const seen = { path: req.url ?? "", method: body.method ?? "" };
      calls.push(seen);
      handler(seen, body, req, res);
    });
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  try {
    await run(url, calls);
  } finally {
    server.closeAllConnections?.();
    await new Promise<void>((r) => server.close(() => r()));
  }
}

const toolCalls = (calls: Seen[]) => calls.filter((c) => c.method === "tools/call");

describe("MCP HTTP tools/call delivery", () => {
  test("a connection reset after the server received tools/call is not re-sent and is reported as unknown", async () => {
    await withServer(
      (seen, _body, req) => { if (seen.method === "tools/call") req.socket.destroy(); },
      async (url, calls) => {
        const conn = new McpConnection("s", { url, transport: "http" });
        const result = await conn.callTool("write_thing", { a: 1 });
        assert.equal(toolCalls(calls).length, 1, `tools/call delivered ${toolCalls(calls).length} times: ${JSON.stringify(calls)}`);
        assert.equal(result.success, false);
        assert.match(result.error ?? "", /outcome unknown/i);
        assert.equal(result.outcomeUnknown, true);
      },
    );
  });

  test("a request timeout is reported as unknown and does not re-send", async () => {
    await withServer(
      (seen, _body, _req, _res) => { void seen; /* never answer */ },
      async (url, calls) => {
        const conn = new McpConnection("s", { url, transport: "http" });
        const result = await conn.callTool("write_thing", {}, 150);
        assert.equal(toolCalls(calls).length, 1);
        assert.equal(result.outcomeUnknown, true);
      },
    );
  });

  test("a definitive 404 on /message still falls back to the legacy base URL exactly once", async () => {
    await withServer(
      (seen, body, _req, res) => {
        if (seen.path.endsWith("/message")) { res.statusCode = 404; res.end("no route"); return; }
        res.setHeader("Content-Type", "application/json");
        res.end(JSON.stringify({ jsonrpc: "2.0", id: body.id, result: { content: [{ type: "text", text: "done" }] } }));
      },
      async (url, calls) => {
        const conn = new McpConnection("s", { url, transport: "http" });
        const result = await conn.callTool("write_thing", {});
        assert.equal(result.success, true);
        assert.equal(result.output, "done");
        assert.deepEqual(calls.map((c) => c.path), ["/message", "/"]);
      },
    );
  });

  test("a read request (tools/list) still tries the legacy URL after a network failure", async () => {
    await withServer(
      (seen, body, req, res) => {
        if (seen.path.endsWith("/message")) { req.socket.destroy(); return; }
        res.setHeader("Content-Type", "application/json");
        res.end(JSON.stringify({ jsonrpc: "2.0", id: body.id, result: { tools: [] } }));
      },
      async (url, calls) => {
        const conn = new McpConnection("s", { url, transport: "http" });
        const result = await conn.sendRequest("tools/list", {});
        assert.deepEqual(result, { tools: [] });
        assert.equal(calls.length, 2);
      },
    );
  });
});

