/**
 * An unknown external outcome is never reported as a confirmed failure (docs/INVARIANTS.md I-EFFECT-2).
 *
 * A timeout, cancel or lost connection on an effectful tool means the effect may have happened. The receipt says so
 * (`outcomeUnknown`, model-visible "OUTCOME UNKNOWN" wording), and a mutating tool in that state counts as having
 * possibly mutated the candidate, so the unverified-change obligation is raised. A plain, confirmed failure
 * is unchanged.
 */
import { test, describe } from "node:test";
import assert from "node:assert";
import { ExecutionSpine, CandidateMutationEvent, InvocationContext, InvocationRequest } from "../src/core/spine.js";
import { createDefaultRegistry } from "../src/core/capabilities.js";
import type { ExecutionResult } from "../src/types.js";

const context: InvocationContext = { workspaceRoot: "/workspace", dryRun: false, readOnly: false };
const request = (toolName: string, args: Record<string, unknown>): InvocationRequest => ({
  taskId: "t", actor: "agent", executionDomain: "agent_orchestration", toolName, args,
});

async function run(toolName: string, args: Record<string, unknown>, result: ExecutionResult) {
  const spine = new ExecutionSpine({ registry: createDefaultRegistry() });
  const mutations: CandidateMutationEvent[] = [];
  spine.setHook("candidateMutation", async (e) => { mutations.push(e); });
  spine.registerHandler(toolName, async () => result);
  const receipt = await spine.execute(request(toolName, args), context);
  return { receipt, mutations };
}

describe("unknown outcome through the execution spine", () => {
  test("a timed-out mutating tool is UNKNOWN, possibly mutated, and says so to the model", async () => {
    const { receipt, mutations } = await run("write_file", { path: "a.txt", content: "x" },
      { success: false, output: "", error: "RPC request timed out", timedOut: true });
    assert.equal(receipt.success, false);
    assert.equal(receipt.outcomeUnknown, true);
    assert.match(receipt.error ?? "", /OUTCOME UNKNOWN/);
    assert.equal(receipt.candidateMutated, true);
    assert.equal(mutations.length, 1);
  });

  test("a lost-connection result flagged outcomeUnknown is treated the same way", async () => {
    const { receipt } = await run("write_file", { path: "a.txt", content: "x" },
      { success: false, output: "", error: "Rust core RPC daemon disconnected", outcomeUnknown: true });
    assert.equal(receipt.outcomeUnknown, true);
    assert.match(receipt.error ?? "", /OUTCOME UNKNOWN/);
  });

  test("a confirmed failure stays a failure: not unknown, not mutated", async () => {
    const { receipt, mutations } = await run("write_file", { path: "a.txt", content: "x" },
      { success: false, output: "", error: "permission denied" });
    assert.equal(receipt.outcomeUnknown, undefined);
    assert.equal(receipt.error, "permission denied");
    assert.equal(receipt.candidateMutated, false);
    assert.equal(mutations.length, 0);
  });

  test("a read-only tool that times out is not marked as mutating the candidate", async () => {
    const { receipt } = await run("read_file", { path: "a.txt" },
      { success: false, output: "", error: "timed out", timedOut: true });
    assert.equal(receipt.candidateMutated, false);
  });

  test("a successful call is unchanged", async () => {
    const { receipt } = await run("write_file", { path: "a.txt", content: "x" }, { success: true, output: "ok" });
    assert.equal(receipt.outcomeUnknown, undefined);
    assert.equal(receipt.candidateMutated, true);
  });
});
