/**
 * Stable identity of a tool call's intent: tool name plus canonical arguments, hashed.
 *
 * Recorded with the write-ahead operation record so that, after a crash with an unknown outcome, a later identical
 * call can be recognised as a possible duplicate of the interrupted one (docs/INVARIANTS.md I-EFFECT-3). The hash, not
 * the arguments, is stored: arguments may carry secrets, and `argsSummary` is already truncated.
 *
 * Deliberately separate from repeated_calls.callKey (per-turn loop ring) and execution_tracking.actionIdentity
 * (per-task ledger keyed with workspace state): those answer "is the model looping", this answers "is this the call
 * that may already have happened". They change for different reasons, so they are not shared.
 */
import { createHash } from "node:crypto";

function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const key of Object.keys(value as Record<string, unknown>).sort()) {
      const v = (value as Record<string, unknown>)[key];
      if (v !== undefined && v !== null) out[key] = canonical(v);
    }
    return out;
  }
  return value;
}

export function argsFingerprint(toolName: string, args: unknown): string {
  return createHash("sha256").update(JSON.stringify([toolName, canonical(args ?? {})])).digest("hex");
}
