/**
 * After a crash that left a tool call with an UNKNOWN outcome, an identical call is not silently repeated
 * (docs/INVARIANTS.md I-EFFECT-3). Plain resume (not the operation runner) in auto mode: the model re-issues the very
 * command whose effect may already have happened; without an operator it is refused, and the command does not run
 * again. A different command is unaffected. Scenario: initial state = durable in-flight intent record with the call's
 * argsHash; trigger = resume + identical call; invariant = no second execution; evidence = counter file + model-visible
 * refusal.
 */
import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AutonomousAgent } from "../src/agent.js";
import { DurableStateManager } from "../src/core/state.js";
import { argsFingerprint } from "../src/core/operation_identity.js";
import { makeRepo, startGateway } from "./helpers/fixtures.js";

function isolatedHome<T>(run: (home: string) => Promise<T>): Promise<T> {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-reissue-home-"));
  const saved = { HOME: process.env.HOME, XDG: process.env.XDG_CONFIG_HOME };
  process.env.HOME = home;
  process.env.XDG_CONFIG_HOME = path.join(home, ".config");
  return run(home).finally(() => {
    process.env.HOME = saved.HOME;
    if (saved.XDG === undefined) delete process.env.XDG_CONFIG_HOME; else process.env.XDG_CONFIG_HOME = saved.XDG;
  });
}

async function scenario(reissue: "identical" | "different") {
  return isolatedHome(async (home) => {
    const repo = makeRepo();
    const stateDir = path.join(home, "tasks");
    const counter = path.join(home, "counter.txt");
    const interrupted = `echo ran >> '${counter}'`;
    const second = reissue === "identical" ? interrupted : `echo other >> '${counter}'`;
    const config = { endpoint: "", model: "m", maxSteps: 6, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true } as any;
    const make = (url: string) => {
      const agent = new AutonomousAgent({ ...config, endpoint: url }, 1, undefined, { durable: true });
      const a = agent as any;
      a.stateManager = new DurableStateManager({ baseDir: stateDir, workspacePaths: [a.primaryWorkspacePathIdentity] });
      a.ui = new Proxy({}, { get: () => () => {} });
      return agent;
    };
    const gw1 = await startGateway((n) => n === 1
      ? { kind: "tools", calls: [{ name: "run_command", args: { command: interrupted } }] }
      : { kind: "text", content: "done" });
    const first = make(gw1.url);
    let taskId = "";
    try {
      await first.runTurn("run the counter command");
      taskId = first.getTaskId();
    } finally { first.shutdown(); await gw1.close(); }
    assert.equal(fs.readFileSync(counter, "utf8"), "ran\n", "the first run executed once");

    // Crash after the effect, before the acknowledgement: the intent record is still in flight.
    const sm = new DurableStateManager({ baseDir: stateDir, workspacePaths: [(first as any).primaryWorkspacePathIdentity] });
    sm.recordOperationStart(taskId, {
      invocationId: "call_crashed", seq: 99, toolName: "run_command",
      argsSummary: JSON.stringify({ command: interrupted }).slice(0, 200),
      argsHash: argsFingerprint("run_command", { command: interrupted }),
    });

    const gw2 = await startGateway((n) => n === 1
      ? { kind: "tools", calls: [{ name: "run_command", args: { command: second } }] }
      : { kind: "text", content: "done" });
    const resumed = make(gw2.url);
    try {
      await resumed.recoverFromTaskState(taskId);
      await resumed.runTurn("continue", undefined, { resume: true });
      const toolText = (gw2.requests[1] as any)?.messages?.filter((m: any) => m.role === "tool").map((m: any) => String(m.content)).join("\n") ?? "";
      return { lines: fs.readFileSync(counter, "utf8").split("\n").filter(Boolean), toolText };
    } finally { resumed.shutdown(); await gw2.close(); fs.rmSync(repo, { recursive: true, force: true }); }
  });
}

test("I-EFFECT-3: an identical call after an interrupted one is refused, not re-run", async () => {
  const { lines, toolText } = await scenario("identical");
  assert.deepEqual(lines, ["ran"], `the command ran again: ${JSON.stringify(lines)}`);
  assert.match(toolText, /interrupted with an unknown outcome/);
});

test("I-EFFECT-3: a different call after an interrupted one still runs", async () => {
  const { lines } = await scenario("different");
  assert.deepEqual(lines, ["ran", "other"]);
});
